const D = { scale:1, energy:.6, hue:48, speed:1, density:.5, x:.5, y:.9, chub:.5, sweep:.6, seed:0, pose:'auto', style:'chalkboard', act:'concert' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI*2;
const md = (a,n)=>((a%n)+n)%n;
const frc = v=>v-Math.floor(v);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const fr = i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u = Math.min(width,height);
const sc = u*P.scale/360;
const bt = K.beat*P.speed;
const H = md(P.hue,360);
const en = P.energy*(.55+.5*K.intensity);
const chub = .85+P.chub*.55;

const style=P.style;
const isBoard=style==='chalkboard', isSketch=style==='sketch', isSilh=style==='silhouette', isNeon=style==='neon', isNoir=style==='noir';

let chalkH=0, chalkS=0, chalkB=95, glow=false;
let boardBg=[150,22,13];
if(isSketch){ chalkH=28; chalkS=14; chalkB=26; boardBg=[38,12,88]; }
else if(isNeon){ chalkH=H; chalkS=72; chalkB=100; glow=true; boardBg=[240,45,7]; }
else if(isNoir){ chalkH=md(H+4,360); chalkS=8; chalkB=94; boardBg=[228,26,6]; }
else if(isSilh){ chalkH=0; chalkS=0; chalkB=8; boardBg=[40,9,88]; }

// ---- program ----
let pose=P.pose;
if(pose==='auto') pose = (K.intensity>.72)?'flourish':'conduct';
let poseAmp=1, poseLift=1;
if(pose==='flourish'){ poseAmp=1.35; poseLift=1.5; }
else if(pose==='rest'){ poseAmp=0.5; poseLift=0.3; }

const patternBeat = (P.act==='largo')? bt*0.5 : bt;
const beatInBar = md(patternBeat,4);
const seg = Math.floor(beatInBar)%4;
const f = frc(beatInBar);
const ease = f<.5 ? 2*f*f : 1-Math.pow(-2*f+2,2)/2;
let ps = (19 + en*11) * poseAmp;
if(P.act==='crescendo') ps *= (0.72+0.5*K.intensity);
if(P.act==='largo') ps *= 0.85;

// 4/4 ictus pattern: down, left, right, up
const PAT=[[0,1],[-1.12,.15],[1.15,.12],[0,-1.18]];
const a0=PAT[seg], a1=PAT[(seg+1)%4];
const rx=(a0[0]*(1-ease)+a1[0]*ease)*ps;
const ry=(a0[1]*(1-ease)+a1[1]*ease)*ps + K.pulse*2.2;

let armLift = clp(K.intensity*0.7+K.swell*0.5,0,1)*24*poseLift;
if(P.act==='crescendo') armLift += K.section*2.2;
armLift = clp(armLift,0,60);

const CRx=34, CRy=-138-armLift;
const CLx=-34, CLy=-138-armLift;
const handRx=CRx+rx, handRy=CRy+ry;
const batonTx=CRx+rx*1.7, batonTy=CRy+ry*1.7;
const handLx=CLx - rx*0.5, handLy=CLy + ry*0.5 - armLift*0.4;

const tailSway = Math.sin(bt*Math.PI)*8*en*P.sweep + A.lowmid*6;
const bodyLean = Math.sin(bt*Math.PI*0.5)*0.02*en;
const headBob = Math.sin(bt*Math.PI)*2.2*en;
const shW=46*chub;

// ---- trail ----
if(!S.trail || S.trail.length>240) S.trail=[];
S.trail.push([batonTx,batonTy]);
if(S.trail.length>46) S.trail.shift();

// ---- chalk helpers ----
function chalk(x1,y1,x2,y2,w,a){
  const dx=x2-x1, dy=y2-y1, L=Math.hypot(dx,dy), n=Math.max(1,Math.floor(L/5));
  const key=Math.floor(x1*0.7+y2*1.3);
  for(let i=0;i<n;i++){
    if(fr(i+key)<0.13) continue;
    const t0=i/n, t1=(i+1)/n, j=w*0.55;
    const jx=(fr(i*2.3+key)-.5)*j, jy=(fr(i*2.7+key+5)-.5)*j;
    strokeWeight(w*(0.55+0.6*fr(i+3+key)));
    stroke(chalkH,chalkS,chalkB,a*(0.5+0.5*fr(i*1.7+key)));
    line(x1+dx*t0+jx,y1+dy*t0+jy,x1+dx*t1+jx,y1+dy*t1+jy);
  }
}
function cpath(pts,closed,w,a){
  if(glow){ push(); blendMode(ADD); noFill(); stroke(chalkH,chalkS,100,a*0.35); strokeWeight(w*3.4); strokeJoin(ROUND);
    beginShape(); for(const p of pts) vertex(p[0],p[1]); if(closed) endShape(CLOSE); else endShape(); pop(); }
  const m=pts.length;
  for(let i=0;i<m-1;i++) chalk(pts[i][0],pts[i][1],pts[i+1][0],pts[i+1][1],w,a);
  if(closed) chalk(pts[m-1][0],pts[m-1][1],pts[0][0],pts[0][1],w,a);
}
function fillPath(pts){ noStroke(); beginShape(); for(const p of pts) vertex(p[0],p[1]); endShape(CLOSE); }

// ---- geometry ----
function coatPts(){
  return [
    [-shW/2,-150],[-shW/2-5,-118],[-shW*0.44,-96],
    [-shW*0.52+tailSway*0.7,-52],[-8+tailSway*0.5,-90],[0,-70],[8+tailSway*0.5,-90],
    [shW*0.52+tailSway*0.7,-52],[shW*0.44,-96],[shW/2+5,-118],[shW/2,-150]
  ];
}
const HC=[0,-170+headBob], HR=14;
function legs(){ return [[[-11,-96],[-10,-48],[-11,-2]],[[11,-96],[10,-48],[11,-2]]]; }

// ---- render ----
push();
translate(P.x*width,P.y*height);
scale(sc);

// board / ground panel
noStroke();
fill(boardBg[0],boardBg[1],boardBg[2], isSilh?96:100);
rect(-132,-206,264,224,10);
if(isBoard||isNoir){ // chalk tray + faint ghost scribbles
  fill(28,30,22,100); rect(-132,14,264,8,2);
  stroke(chalkH,chalkS,chalkB,7); strokeWeight(1);
  for(let i=0;i<5;i++){ const gy=-190+i*8; line(-118,gy,-118+40+fr(i*9)*30,gy); }
  noStroke();
}
// vignette so figure reads
if(!isSilh){ push(); blendMode(MULTIPLY); noStroke(); fill(0,0,0,22); rect(-132,-206,264,20); rect(-132,-2,264,20); pop(); }

push();
rotate(bodyLean);

if(isSilh){
  fill(chalkH,chalkS,chalkB,100);
  fillPath(coatPts());
  const lg=legs();
  for(const p of lg){ strokeWeight(7); stroke(chalkH,chalkS,chalkB,100); noFill(); line(p[0][0],p[0][1],p[1][0],p[1][1]); line(p[1][0],p[1][1],p[2][0],p[2][1]); }
  noStroke(); ellipse(HC[0],HC[1],HR*2,HR*2.15);
  // arms as thick capsules
  strokeCap(ROUND);
  stroke(chalkH,chalkS,chalkB,100); strokeWeight(9); noFill();
  line(shW/2-4,-150,handRx,handRy); line(handRx,handRy,batonTx,batonTy);
  line(-shW/2+4,-150,handLx,handLy);
  strokeCap(ROUND);
} else {
  // legs
  const lg=legs();
  for(const p of lg) cpath(p,false,4.2,80);
  chalk(-15,-2,-6,-2,5,80); chalk(6,-2,15,-2,5,80);
  // coat
  cpath(coatPts(),true,4.6,90);
  // back seam + hatching for volume
  chalk(0,-148,0,-96,2.4,55);
  for(let i=0;i<4;i++){ const hy=-140+i*11; chalk(-shW*0.3,hy,-shW*0.12,hy+7,1.6,34*en+20); }
  // collar
  cpath([[-11,-150],[-7,-158],[7,-158],[11,-150]],false,3.4,85);
  // head (back) + hair hatch
  cpath([[HC[0]-HR,HC[1]],[HC[0]-HR*0.8,HC[1]-HR*0.8],[HC[0],HC[1]-HR*1.05],[HC[0]+HR*0.8,HC[1]-HR*0.8],[HC[0]+HR,HC[1]]],false,3.4,88);
  cpath([[HC[0]-HR,HC[1]],[HC[0]-HR*0.7,HC[1]+HR*0.9],[HC[0],HC[1]+HR*1.05],[HC[0]+HR*0.7,HC[1]+HR*0.9],[HC[0]+HR,HC[1]]],false,3.4,88);
  for(let i=0;i<5;i++){ const hx=HC[0]-9+i*4.5; chalk(hx,HC[1]-HR*0.6,hx-1.5,HC[1]-HR*1.02,1.4,60); }
  // arms
  cpath([[shW/2-4,-150],[ (shW/2-4+handRx)/2 + 6,(-150+handRy)/2 ],[handRx,handRy]],false,4,88);
  cpath([[-shW/2+4,-150],[ (-shW/2+4+handLx)/2 - 6,(-150+handLy)/2 ],[handLx,handLy]],false,4,88);
  // hands
  push(); noFill(); stroke(chalkH,chalkS,chalkB,90); strokeWeight(2); ellipse(handRx,handRy,7,7); ellipse(handLx,handLy,6,6); pop();
}

// baton + trail (all styles)
push();
if(isNeon||glow){ push(); blendMode(ADD); stroke(chalkH,chalkS,100,25); strokeWeight(8); noFill();
  beginShape(); for(let i=0;i<S.trail.length;i++){ const p=S.trail[i]; curveVertex(p[0],p[1]); } endShape(); blendMode(BLEND); pop(); }
// trail as fading chalk dashes
for(let i=1;i<S.trail.length;i++){
  const p0=S.trail[i-1], p1=S.trail[i]; const fade=i/S.trail.length;
  strokeWeight((0.6+fade*2.4));
  const th = isNeon? chalkH : (isSilh?0:chalkH);
  stroke(isSilh?0:th, isSilh?0:(isNeon?60:chalkS), isSilh?45:chalkB, fade*70);
  line(p0[0],p0[1],p1[0],p1[1]);
}
// baton stick
stroke(isSilh?0:chalkH,isSilh?0:(chalkS*0.6),isSilh?30:100, 95); strokeWeight(2.6);
line(handRx,handRy,batonTx,batonTy);
noStroke(); fill(isSilh?0:48,isSilh?0:30,isSilh?30:100,95); ellipse(batonTx,batonTy,5,5);
// ictus spark on the beat
if(K.pulse>0.35 && !isSilh){ push(); blendMode(ADD); noStroke(); fill(chalkH,chalkS*0.5,100,clp(K.pulse*55+A.treble*30,0,70)); ellipse(batonTx,batonTy,10+K.pulse*10,10+K.pulse*10); blendMode(BLEND); pop(); }
pop();

pop(); // bodyLean

// chalk dust drifting from baton (density) — baseline shimmer
const nd=Math.floor(P.density*12);
noStroke();
for(let i=0;i<nd;i++){ const ph=frc(K.t*(.18+.06*fr(i))+fr(i*3)); const dx=batonTx+(fr(i*5)-.5)*26, dy=batonTy+ph*40; fill(isSilh?0:chalkH,isSilh?0:chalkS*0.5,isSilh?40:chalkB, clp(30*(1-ph),0,34)); ellipse(dx+Math.sin(K.t*2+i)*4,dy,1.8,1.8); }

blendMode(BLEND);
pop();
